local function CreateToggleButton(parent)
	local btn = Instance.new("ImageButton")
	btn.Name = "ToggleButton"
	btn.Parent = parent

	btn.Size = UDim2.new(0, 65, 0, 65)
	btn.Position = UDim2.new(0, 30, 0, 30)
	btn.BackgroundTransparency = 1
	btn.Image = "rbxassetid://132604725696137"
	btn.ZIndex = 999
	btn.Active = true

	Instance.new("UICorner", btn).CornerRadius = UDim.new(1, 0)

	return btn
end

local function EnableDrag(guiObject)
	local UIS = game:GetService("UserInputService")

	local dragging = false
	local dragStart, startPos

	guiObject.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = true
			dragStart = input.Position
			startPos = guiObject.Position
		end
	end)

	guiObject.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
			dragging = false
		end
	end)

	UIS.InputChanged:Connect(function(input)
		if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
			local delta = input.Position - dragStart
			guiObject.Position = UDim2.new(
				startPos.X.Scale,
				startPos.X.Offset + delta.X,
				startPos.Y.Scale,
				startPos.Y.Offset + delta.Y
			)
		end
	end)
end

local function SetupToggle(button, frame)
	local visible = true

	button.Activated:Connect(function()
		visible = not visible
		frame.Visible = visible
	end)
end

local function InitToggle(screenGui, frame)
	local toggle = CreateToggleButton(screenGui)
	EnableDrag(toggle)
	SetupToggle(toggle, frame)
end

